unit RttiDispatchDemo;

interface

uses Classes, TypInfo;

type
  TConfig = class(TPersistent)
  published
    property Host : string read FHost write FHost;
    property Port : Integer read FPort write FPort;
  private
    FHost : string;
    FPort : Integer;
  end;

procedure ApplyOverride(Obj : TObject; const AProp, AValue : string);

implementation

procedure ApplyOverride(Obj : TObject; const AProp, AValue : string);
var
  Info : PPropInfo;
begin
  // Walks RTTI to bind by name -- no compile-time guarantee that
  // AProp exists. Silently no-ops when the property is absent.
  Info := GetPropInfo(Obj.ClassInfo, AProp);
  if Info = nil then Exit;
  SetStrProp(Obj, Info, AValue);
end;

end.
